public class Main {
    public static void main(String[] args) {
        printBar(7);
        printBar(7, '#');
        printBar(3, '=');
    }

    // The short version: supplies the default, then hands over.
    static void printBar(int length) {
        printBar(length, '*');
    }

    // The long version: the only place the real work lives.
    static void printBar(int length, char symbol) {
        for (int i = 1; i <= length; i++) {
            System.out.print(symbol);
        }
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        report("Amara", 92);
        report("Sam", 92, true);
        report("Mia", 150);
    }

    // Two arguments: assume it is not a retake.
    static void report(String name, int score) {
        report(name, score, false);
    }

    static void report(String name, int score, boolean retake) {
        if (!isValid(score)) {
            System.out.println(name + ": " + score + " is not a valid score");
            return;
        }
        String line = name + ": " + score;
        if (retake) {
            line = line + " (retake)";
        }
        System.out.println(line);
    }

    static boolean isValid(int score) {
        return score >= 0 && score <= 100;
    }
}

